/* Self-contained reports: no external assets, credentials or network calls. */
(() => {
  function renderReport(report) {
    const add = (tag, text, parent = document.body) => {
      const element = document.createElement(tag);
      if (text) element.textContent = text;
      parent.append(element);
      return element;
    };
    const sourceLink = (source, parent, index) => {
      const label = `${index ? `[${index}] ` : ''}${source.title}`;
      try {
        if (new URL(source.url).protocol !== 'https:') throw Error();
        const a = add('a', label, parent); a.href = source.url;
        a.target = '_blank'; a.rel = 'noopener noreferrer';
      } catch { add('span', label, parent); }
    };
    const header = add('header');
    add('div', '✳ YodaX', header).className = 'brand';
    add('p', 'MARKET RESEARCH REPORT · Generated by YodaX', header);
    add('h1', report.question || 'Market outlook', header);
    add('p', `Research date: ${report.date || 'Not recorded'} · Model: ${report.model || 'Not recorded'}`, header);
    const tools = add('nav', '', header);
    const print = add('button', 'Print / Save PDF', tools); print.onclick = () => window.print();
    const download = add('button', 'Download interactive report', tools);
    download.onclick = () => {
      const file = new Blob(['<!doctype html>' + document.documentElement.outerHTML], {type:'text/html'});
      const url = URL.createObjectURL(file); const a = document.createElement('a');
      a.href = url; a.download = 'YodaX-research-report.html'; a.click();
      setTimeout(() => URL.revokeObjectURL(url), 1000);
    };
    const main = add('main');
    const outlook = add('section', '', main); outlook.className = 'outlook';
    add('p', 'CONDITIONAL OUTLOOK', outlook); add('h2', report.outlook, outlook);
    add('p', 'Research scenario, not a validated numerical price prediction. Not investment advice.', outlook);
    if (report.saved_prediction) {
      const forecast = add('section', '', main);
      add('h2', 'Tracked stock prediction', forecast);
      const tracked = report.tracked_prediction;
      const p = tracked?.payload;
      add('p', `${report.saved_prediction.symbol} · ${report.saved_prediction.horizon_sessions} trading sessions · ${tracked?.state || 'queued'}`, forecast);
      if (p?.predicted) {
        add('h2', `$${p.predicted.toFixed(2)} USD · Target close ${p.target}`, forecast);
        add('p', `Estimated range $${p.low.toFixed(2)}–$${p.high.toFixed(2)}. Issued ${p.issued_at}. Model ${p.model}, revision ${p.model_revision}.`, forecast);
        if (p.evaluation) add('p', `Actual close $${p.actual.toFixed(2)} · Score ${p.evaluation.score.toFixed(1)}/100 · Absolute error $${p.evaluation.absolute_error.toFixed(2)}`, forecast);
      } else add('p', 'Awaiting the scheduled model run. No numerical prediction has been issued yet.', forecast);
      add('p', 'This report is a snapshot. Refresh the prediction section and regenerate it for updated results.', forecast);
    }
    const analysis = add('section', '', main); add('h2', 'The analysis', analysis);
    const answer = add('p', '', analysis); answer.className = 'answer';
    // Internal citation links keep the source numbering used in the answer.
    let offset = 0;
    for (const match of report.answer.matchAll(/\[([0-9, ]+)\]/g)) {
      answer.append(document.createTextNode(report.answer.slice(offset, match.index)));
      for (const id of match[1].split(',').map(Number)) {
        if (report.sources[id-1]) { const a = add('a', `[${id}]`, answer); a.href = `#source-${id}`; }
      }
      offset = match.index + match[0].length;
    }
    answer.append(document.createTextNode(report.answer.slice(offset)));
    if (report.note) add('p', report.note, analysis).className = 'note';
    const context = add('section', '', main); add('h2', 'The evidence map', context);
    add('p', 'Select a node to explore its context and sources. Connections describe proposed mechanisms, not proven causation.', context);
    const legend = add('p', '', context);
    for (const [label, color] of [['Evidence','#c9ddff'],['Mechanism','#e0d1ff'],['Risk','#ffd2ac'],['Outlook','#ffd75e']]) {
      const key = add('span', label, legend); key.style.background = color;
    }
    legend.className = 'legend';
    const scroller = add('div', '', context); scroller.className = 'map';
    const ns = 'http://www.w3.org/2000/svg';
    const svg = document.createElementNS(ns, 'svg'); scroller.append(svg);
    const groups = [report.nodes.filter(n=>n.kind==='evidence'),report.nodes.filter(n=>['mechanism','risk'].includes(n.kind)),report.nodes.filter(n=>n.kind==='outlook')];
    const height = Math.max(280, ...groups.map(g=>g.length*105+30));
    svg.setAttribute('viewBox', `0 0 940 ${height}`); svg.setAttribute('aria-label','Interactive evidence map');
    const positions = new Map();
    groups.forEach((g,col)=>g.forEach((n,i)=>positions.set(n.id,{x:20+col*315,y:25+i*105})));
    function shape(tag, attrs, text='') {
      const e=document.createElementNS(ns,tag);Object.entries(attrs).forEach(([k,v])=>e.setAttribute(k,v));e.textContent=text;svg.append(e);return e;
    }
    for (const edge of report.edges) {
      const a=positions.get(edge.from),b=positions.get(edge.to); if(!a||!b)continue;
      shape('path',{d:`M${a.x+130},${a.y+37} L${b.x+130},${b.y+37}`,stroke:'#8b8b98','stroke-width':2,fill:'none'});
    }
    const detail = add('div', '', context); detail.className='detail'; detail.setAttribute('aria-live','polite');
    const colors={evidence:'#c9ddff',mechanism:'#e0d1ff',risk:'#ffd2ac',outlook:'#ffd75e'};
    function select(node) {
      detail.replaceChildren();add('small',node.kind.toUpperCase(),detail);add('h3',node.label,detail);add('p',node.detail,detail);
      for(const id of node.source_ids) if(report.sources[id-1])sourceLink(report.sources[id-1],add('p','',detail),id);
      for(const edge of report.edges.filter(e=>e.from===node.id||e.to===node.id)) {
        const from=report.nodes.find(n=>n.id===edge.from),to=report.nodes.find(n=>n.id===edge.to);
        if(from&&to)add('p',`${from.label} → ${edge.label} → ${to.label}`,detail);
      }
    }
    for(const node of report.nodes) {
      const p=positions.get(node.id); if(!p)continue;
      const rect=shape('rect',{x:p.x,y:p.y,width:265,height:76,rx:13,fill:colors[node.kind],tabindex:0,role:'button','aria-label':node.label});
      rect.onclick=()=>select(node);rect.onkeydown=e=>{if(['Enter',' '].includes(e.key)){e.preventDefault();select(node);}};
      const label=shape('text',{x:p.x+14,y:p.y+29,'font-size':13,fill:'#151515','pointer-events':'none'});
      const words=node.label.split(/\s+/);let lines=[''];for(const word of words){if((lines.at(-1)+' '+word).length>30)lines.push(word);else lines[lines.length-1]+=(lines.at(-1)?' ':'')+word;}
      lines.slice(0,3).forEach((line,i)=>{const t=document.createElementNS(ns,'tspan');t.setAttribute('x',p.x+14);t.setAttribute('dy',i?'17':'0');t.textContent=line;label.append(t);});
    }
    select(report.nodes.find(n=>n.kind==='outlook')||report.nodes[0]);
    const appendix = add('details','',main);add('summary','All mapped context',appendix);
    for(const node of report.nodes){add('h3',node.label,appendix);add('p',`${node.kind}: ${node.detail}`,appendix);}
    const refs=add('section','',main);add('h2','References',refs);
    add('p','Sources were retrieved as headlines, not verified full articles.',refs);
    const list=add('ol','',refs);
    report.sources.forEach((s,i)=>{const li=add('li','',list);li.id=`source-${i+1}`;sourceLink(s,li);add('small',`${s.publisher||''} · ${s.published||'Date unavailable'}`,li);});
    if(!report.sources.length)add('p','No current sources were available. General principles and assumptions are identified above.',refs);
    add('footer','Generated by YodaX · Evidence, context, and a conditional outlook.');
  }
  const css = `*{box-sizing:border-box}body{margin:0;background:#f3f3f5;color:#18181b;font:16px/1.65 system-ui,sans-serif}header,main,footer{max-width:1040px;margin:auto;padding:32px}header{background:#111114;color:#ffffff;border-radius:0 0 28px 28px}.brand{font-size:34px;font-weight:750}h1{font-size:clamp(26px,4vw,42px);line-height:1.2}h2{line-height:1.35}header p,small{font-size:12px}nav{display:flex;gap:12px;flex-wrap:wrap}button{padding:12px 18px;border:0;border-radius:24px;background:#ffffff;color:#111114;font:inherit;cursor:pointer}section,details{background:white;padding:26px;margin-bottom:22px;border:1px solid #dedee5;border-radius:18px}.outlook{background:#fff2bd}.answer{white-space:pre-wrap}a{color:#294ab8;overflow-wrap:anywhere}.note{border-left:3px solid #de782a;padding:12px}.map{overflow:auto}svg{width:100%;min-width:700px;display:block}rect{cursor:pointer}rect:focus{outline:3px solid #111114}.detail{background:#f0effa;border-radius:12px;padding:20px}.legend{color:#18181b;display:flex;gap:8px;flex-wrap:wrap}.legend span{padding:4px 12px;border-radius:20px;font-size:12px;font-weight:650}small{display:block}li{margin:16px 0}summary{cursor:pointer;font-weight:600}footer{font-size:13px}@media(max-width:600px){header,main,footer{padding:20px}section{padding:18px}}@media print{body{background:white;font-size:11px}nav{display:none}header{color:#111114;background:white}section{break-inside:avoid}svg{min-width:0}details{display:block}details>*{display:block}a{color:inherit}header,main,footer{padding:12px}}`;
  window.yodaxReport = report => {
    const data=JSON.stringify(report).replace(/</g,'\\u003c');
    // Clear a downloaded report's saved DOM before rebuilding its interactions.
    const html=`<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>YodaX — Research report</title><style>${css}</style><script>window.addEventListener("DOMContentLoaded",()=>{document.body.replaceChildren();(${renderReport.toString()})(${data});});<\/script></head><body></body></html>`;
    const url=URL.createObjectURL(new Blob([html],{type:'text/html'}));
    const a=document.createElement('a');a.href=url;a.target='_blank';a.rel='noopener';a.click();
    setTimeout(()=>URL.revokeObjectURL(url),60000);
  };
})();
